def _filtered_input_refs(view):
    """Non-substituted evaluation input evidence. View/inventory locators stripped to owner records."""
    objects, blobs = view["objects"], view["blobs"]
    plain = []
    views = []
    inventories = []
    for ref in view.get("evaluationInputRefs") or []:
        domain = ref.get("domain")
        digest = ref.get("digest")
        if domain in SUBSTITUTED_INPUT_REF_DOMAINS:
            continue
        if not digest:
            continue
        if domain == "view":
            views.append(_view_evidence(objects, "view2:" + digest))
        elif domain == "subject-inventory":
            inventories.append(_inventory_evidence(blobs, digest))
        else:
            plain.append({"domain": domain, "digest": digest})
    views.sort(key=lambda v: canonical.canonical(v))
    inventories.sort(key=lambda v: canonical.canonical(v))
    plain.sort(key=lambda r: (r["domain"].encode(), r["digest"].encode()))
    return plain, views, inventories


def _execution_inputs_evidence(view, axis):
    """Compare execution-inputs minus Plan locators when both sides captured them.

    planId/executionPlanId/analysisSpecDigest remint with policy/scope/emission.
    Physical store censuses are not in the semantic record. Missing capture on
    both sides is omitted (root may still be activating the digest).
    """
    blobs = view["blobs"]
    found = [r for r in (view.get("evaluationInputRefs") or []) if r.get("domain") == "execution-inputs"]
    if not found:
        return None
    digest = found[0]["digest"]
    if digest not in blobs:
        return {"digestPresent": True, "body": None}
    try:
        rec = canonical.parse(blobs[digest])
    except Exception:
        return {"digestPresent": True, "body": None}
    if not isinstance(rec, dict):
        return {"digestPresent": True, "body": None}
    selected = []
    for ref in rec.get("selectedRefs") or []:
        if ref.get("domain") in SUBSTITUTED_INPUT_REF_DOMAINS:
            continue
        selected.append({"domain": ref.get("domain"), "digest": ref.get("digest")})
    selected.sort(key=lambda r: ((r["domain"] or "").encode(), (r["digest"] or "").encode()))
    ev = {
        "enumerationPlanDigest": rec.get("enumerationPlanDigest"),
        "nativeCoverageAccounts": rec.get("nativeCoverageAccounts"),
        "selectedRefs": selected,
        "candidateResultRefs": rec.get("candidateResultRefs"),
    }
    if axis != "E0":
        ev["evaluatorClosure"] = rec.get("evaluatorClosure")
    return ev


def _closures_by_kind(plan, objects, exclude_kinds=()):
    out = {}
    for cid in plan.get("semanticClosures") or []:
        if cid not in objects:
            raise Refusal("REQUEST.PRECONDITION_FAILED", "EVALUATION.PROJECTION_INPUT_INCOMPLETE", "semantic closure missing", cid)
        kind = objects[cid][1]["kind"]
        if kind in exclude_kinds:
            continue
        out.setdefault(kind, []).append(cid)
    for kind in out:
        out[kind] = sorted(out[kind])
    return {k: out[k] for k in sorted(out)}


def semantic_source_inputs(view, axis: str) -> dict:
    """Non-substituted semantic inputs of an admitted Run.

    E1..E3 re-evaluate retained current facts: snapshot, config, native context,
    Plan-selected imports, foundation walked scope, capability bytes, closures,
    fact/coverage evidence, and inventory rows. View/inventory/execution-input
    envelopes remint Plan locators; those locators are stripped. policy/waiver/
    emission/analysis-spec/rule-program are axis substitutions and are omitted.

    E0 may use the prior detector, so detector closures are excluded there.
    """
    plan = view["plan"]
    objects = view["objects"]
    exclude = ("detector",) if axis == "E0" else ()
    plain, views, inventories = _filtered_input_refs(view)
    return {
        "snapshotId": plan["snapshotId"],
        "resolvedConfigDigest": plan["resolvedConfigDigest"],
        "nativeContextDigests": sorted(plan.get("nativeContextDigests") or []),
        "importIds": sorted(plan.get("importIds") or []),
        "foundationScopeDigest": plan["scopeDigest"],
        "capabilityManifestBytesDigest": plan["capabilityManifestBytesDigest"],
        "closuresByKind": _closures_by_kind(plan, objects, exclude),
        "inputRefs": plain,
        "viewEvidence": views,
        "inventoryEvidence": inventories,
        "executionInputs": _execution_inputs_evidence(view, axis),
    }


def require_same_source_inputs(pivot_view, current_view, axis) -> None:
    got = semantic_source_inputs(pivot_view, axis)
    want = semantic_source_inputs(current_view, axis)
    if canonical.canonical(got) != canonical.canonical(want):
        raise Refusal(
            "CONFIG.INVALID",
            "EVALUATION.FINDING_JOIN_REFUSED",
            "pivot semantic inputs are not the current Run's non-substituted source evidence",
            axis,
