    except Exception:
        return None
    if not isinstance(body, dict) or body.get("schemaFamily") != DETECTOR_MANIFEST_FAMILY:
        return None
    if body.get("schemaMajor") != 1:
        return None
    validate_profile("urn:opensip:product-v1:workflows:evaluator3:detector-manifest:1", body)
    return body


def admitted_manifest_compatible_with(closure_id, semantics_major, objects, blobs, host) -> list:
    """compatibleClosures from an admitted current-trust closure body.

    Current-trust receipt is host.closures[closureId].trust==admitted. This helper
    does not verify signatures; the host TCB already admitted the closure from a
    retained generation, installed signed release, or signed closureBundle.
    """
    rec = (host or {}).get("closures", {}).get(closure_id)
    if not rec or rec.get("trust") != "admitted" or rec.get("bytes") == "missing":
        return []
    if closure_id not in objects or objects[closure_id][0] != "closure":
        return []
    body = parse_detector_manifest_body(blobs, objects[closure_id][1].get("manifestDigest"))
    if body is None:
        return []
    out = []
    for row in body.get("compatibleClosures") or []:
        if row.get("semanticsMajor") == semantics_major and row.get("closureId"):
            out.append(row["closureId"])
    return sorted(set(out), key=lambda s: s.encode())


def emission_detectors_with_admitted_compatibility(view, host):
